class RAGnarock:
  def __init__(self):
    self.knowledge_base = {}

  def implant_knowledge(self, category, data):
    """Implanta conhecimento na base de dados."""
    if category not in self.knowledge_base:
      self.knowledge_base[category] = []
    self.knowledge_base[category].append(data)

  def retrieve_knowledge(self, category, query=None):
    """Recupera conhecimento da base de dados."""
    if category in self.knowledge_base:
      results = self.knowledge_base[category]
      if query:
        # Implementar lógica para filtrar resultados com base na consulta
        filtered_results = [item for item in results if query in item]
        return filtered_results
      else:
        return results
    else:
      return "Categoria não encontrada."

# Exemplo de uso
rag = RAGnarock()

rag.implant_knowledge("Monomito", ["Crise", "Tesouro", "Resultado", "Retorno", "Nova Vida", "Resolução"])
rag.implant_knowledge("Tecnologia", ["Gemma 2", "Processamento de linguagem natural"])

print(rag.retrieve_knowledge("Monomito")) 
print(rag.retrieve_knowledge("Tecnologia", query="Gemma"))
